import React, { useEffect, useState } from "react";
import api, { setTenantId } from "../services/api";
import ReportViewer from "../components/ReportViewer";

export default function ReportsPage() {
  const tenantId =
    process.env.REACT_APP_TENANT_ID ?? "11111111-1111-1111-1111-111111111111";
  setTenantId(tenantId);

  const [start, setStart] = useState<string>(() => {
    const d = new Date();
    d.setDate(d.getDate() - 30);
    return d.toISOString().slice(0, 16);
  });
  const [end, setEnd] = useState<string>(() => new Date().toISOString().slice(0, 16));

  const [reportJson, setReportJson] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function loadReport() {
    setLoading(true);
    setError(null);

    try {
      const resp = await api.get("/api/reports/data", {
        params: {
          start: new Date(start).toISOString(),
          end: new Date(end).toISOString(),
          clientLocalTime: new Date().toISOString(),
        },
      });

      console.log("Raw API response:", resp.data);

      // Normalize response
      let rows: any[] = [];

      if (Array.isArray(resp.data)) {
        // API returned array directly
        rows = resp.data;
      } else if (Array.isArray(resp.data?.data)) {
        // API returned { data: [...] }
        rows = resp.data.data;
      } else if (Array.isArray(resp.data?.data?.$values)) {
        // .NET serialized objects with $values
        rows = resp.data.data.$values;
      } else if (resp.data) {
        // Single object
        rows = [resp.data];
      }

      const report = {
        reportGeneratedOn: resp.data.reportGeneratedOn ?? new Date().toISOString(),
        data: rows,
      };

      setReportJson(report);
    } catch (err: any) {
      console.error("Error fetching report:", err);
      setError(err?.message || "Failed to load report.");
      setReportJson(null);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadReport();
  }, []);

  return (
    <div>
      <h2>Reports</h2>
      <div style={{ marginBottom: "1rem" }}>
        From{" "}
        <input
          type="datetime-local"
          value={start}
          onChange={(e) => setStart(e.target.value)}
          disabled={loading}
        />
        To{" "}
        <input
          type="datetime-local"
          value={end}
          onChange={(e) => setEnd(e.target.value)}
          disabled={loading}
        />
        <button onClick={loadReport} disabled={loading}>
          {loading ? "Loading..." : "Refresh"}
        </button>
      </div>

      {loading && <p>⏳ Loading report...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}
      {!loading && reportJson && <ReportViewer reportJson={reportJson} />}
      {!loading && !reportJson && !error && <p>No report data available.</p>}
    </div>
  );
}
